const j = $input.first().json;
const b = j.body || j;
const text = b.resume_text || b['Resume text'] || '';
return [{ json: { resume_text: String(text), source: b.source || (j.body ? 'webhook' : 'form'), file_name: b.file_name || '', message_id: b.message_id || '' } }];

const vac = $('Read Vacancy').all().map(i => i.json);
const crit = $('Read Criteria').all().map(i => i.json);
const rules = $('Read Rules').all().map(i => i.json);
const errors = [];
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const num = v => { const n = Number(clean(v).replace(',', '.')); return clean(v) === '' || isNaN(n) ? NaN : n; };

const V = {}; vac.forEach(r => { if (clean(r.key)) V[clean(r.key)] = clean(r.value); });
const R = {}; rules.forEach(r => { if (clean(r.key)) R[clean(r.key)] = clean(r.value); });
['vacancy_id', 'title', 'responsibilities', 'config_version'].forEach(k => { if (!V[k]) errors.push('Vacancy: missing key or empty value: ' + k); });

const numeric = ['top_min', 'maybe_min', 'near_miss_min', 'm2_min_months', 'c1_l1_months', 'c1_l2_months', 'c1_l3_months', 'part_time_factor', 'min_chars', 'max_chars', 'reminder_hours'];
const required = numeric.concat(['prompt_version', 'blocking_flags', 'injection_patterns', 'model_filter', 'model_scorer', 'price_filter_in_per_mtok', 'price_filter_out_per_mtok', 'price_scorer_in_per_mtok', 'price_scorer_out_per_mtok']);
required.forEach(k => { if (!R[k]) errors.push('Rules: missing key or empty value: ' + k); });
const cfgNum = {};
numeric.concat(['price_filter_in_per_mtok', 'price_filter_out_per_mtok', 'price_scorer_in_per_mtok', 'price_scorer_out_per_mtok']).forEach(k => {
  if (R[k]) { const n = num(R[k]); if (isNaN(n)) errors.push('Rules: value is not a number: ' + k + ' = "' + R[k] + '"'); else cfgNum[k] = n; }
});
if (!isNaN(cfgNum.top_min) && !isNaN(cfgNum.maybe_min) && cfgNum.maybe_min > cfgNum.top_min) errors.push('Rules: maybe_min must not exceed top_min');
try { new RegExp(R.injection_patterns || '(?!)', 'i'); } catch (e) { errors.push('Rules: injection_patterns is not a valid regular expression'); }

const yn = v => { const t = clean(v).toLowerCase(); return t === '' ? true : ['yes', 'y', 'true', '1'].indexOf(t) !== -1; };
const pts = clean(R.relevant_product_types || 'software_it').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
pts.forEach(p => { if (['software_it', 'telecom', 'other'].indexOf(p) === -1) errors.push('Rules: relevant_product_types has an invalid value: ' + p + ' (allowed: software_it, telecom, other)'); });
const relevance = { require_customer_facing: yn(R.relevant_requires_customer_facing), require_technical: yn(R.relevant_requires_technical), product_types: pts };

const C = crit.filter(r => clean(r.id) && clean(r.active).toUpperCase() !== 'N').map(r => ({
  id: clean(r.id), type: clean(r.type), name: clean(r.name), weight: clean(r.weight) === '' ? 0 : num(r.weight),
  computed_by: clean(r.computed_by), definition: clean(r.definition),
  levels: [clean(r.level_0), clean(r.level_1), clean(r.level_2), clean(r.level_3)],
  evidence_hint: clean(r.evidence_hint), exclusions: clean(r.exclusions)
}));
if (!C.length) errors.push('Criteria: no active rows');
const scored = C.filter(c => c.type === 'scored');
if (!C.some(c => c.id === 'M1')) errors.push('Criteria: M1 is missing');
if (!C.some(c => c.id === 'M2')) errors.push('Criteria: M2 is missing');
if (!C.some(c => c.id === 'C1')) errors.push('Criteria: C1 is missing');
scored.forEach(c => { if (isNaN(c.weight) || c.weight <= 0) errors.push('Criteria: weight invalid for ' + c.id); if (c.computed_by === 'model' && c.levels.some(l => !l)) errors.push('Criteria: level text missing for ' + c.id); });
const sum = scored.reduce((a, c) => a + (c.weight || 0), 0);
if (scored.length && sum !== 100) errors.push('Criteria: weights of active scored criteria sum to ' + sum + ', expected 100');

if (errors.length) throw new Error('CONFIG ERROR, nothing was processed:\n- ' + errors.join('\n- '));

const optional = { ack_enabled: 'no', ack_template: '', timezone: 'Europe/Zagreb', telegram_chat_id: '' };
Object.keys(optional).forEach(k => { if (R[k] === undefined) R[k] = optional[k]; });
return [{ json: { vacancy: V, criteria: C, rules: R, num: cfgNum, relevance, config_version: V.config_version, prompt_version: R.prompt_version } }];

const cfg = $('Build Config').first().json;
const R = cfg.rules, N = cfg.num;
const inp = $('Normalize Input').first().json;
let raw = String(inp.resume_text || '');
let text = raw.replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F​-‍﻿]/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const flags = [];
const origLen = text.length;
if (text.length > N.max_chars) { text = text.slice(0, N.max_chars); flags.push('truncated'); }
const unreadable = text.length < N.min_chars;
if (unreadable) flags.push('unreadable_text');
text = text.replace(/<\s*\/?\s*RESUME\s*>/gi, '[tag-removed]');
const em = text.match(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/);
const email = em ? em[0].toLowerCase() : '';
const ph = text.match(/(\+?\d[\d\s().\-]{7,}\d)/);
let phone = ph ? ph[1].replace(/[^\d+]/g, '') : '';
if (phone && phone.replace(/\D/g, '').length < 8) phone = '';
if (!email && !phone) flags.push('contact_missing');
function cyrb53(s, seed) { let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed; for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16); }
const hash = cyrb53(text.toLowerCase().replace(/\s+/g, ' '), 7);
let injMatch = '';
try { const m = text.match(new RegExp(R.injection_patterns, 'i')); if (m) { injMatch = m[0].slice(0, 120); flags.push('possible_injection'); } } catch (e) {}
const received = new Date().toISOString();
const candidate_id = 'C-' + cyrb53(email || phone || hash, 3).slice(0, 8);
return [{ json: { message_id: inp.message_id || ('m-' + hash), source: inp.source || 'unknown', file_name: inp.file_name || '', received_at: received, resume_text: text, text_length: text.length, original_length: origLen, email_norm: email, phone_norm: phone, resume_hash: hash, candidate_id, unreadable, flags, injection_regex_match: injMatch } }];

const pc = $('Pre-checks').first().json;
const rows = $('Read Candidates').all().map(i => i.json).filter(r => r && String(r.candidate_id || '').trim() !== '');
const real = rows.filter(r => String(r.tier || '') !== 'DUPLICATE');
const same = real.filter(r => (pc.email_norm && r.email_norm === pc.email_norm) || (!pc.email_norm && pc.phone_norm && r.phone_norm === pc.phone_norm));
let dup_status = 'new', version = 1, prev_candidate_id = '', prev_hr_status = '', prev_hr_decided_at = '', prev_hr_note = '';
const dupOf = real.filter(r => r.resume_hash === pc.resume_hash && (r.email_norm || '') === (pc.email_norm || '') && (r.phone_norm || '') === (pc.phone_norm || ''));
if (dupOf.length) {
  dup_status = 'duplicate';
  prev_candidate_id = dupOf[0].candidate_id;
  version = Number(dupOf[dupOf.length - 1].version) || 1;
} else if (same.length) {
  dup_status = 'new_version';
  version = Math.max.apply(null, same.map(r => Number(r.version) || 1)) + 1;
  prev_candidate_id = same[0].candidate_id;
  const withStatus = same.filter(r => String(r.hr_status || '').trim() !== '').sort((a, b) => String(b.hr_decided_at || '').localeCompare(String(a.hr_decided_at || '')) || ((Number(b.version) || 1) - (Number(a.version) || 1)));
  if (withStatus.length) { prev_hr_status = String(withStatus[0].hr_status).trim(); prev_hr_decided_at = withStatus[0].hr_decided_at || ''; prev_hr_note = withStatus[0].hr_note || ''; }
}
if (pc.source === 'eval') { dup_status = 'new'; version = 1; prev_candidate_id = ''; prev_hr_status = ''; prev_hr_decided_at = ''; prev_hr_note = ''; }
const route = dup_status === 'duplicate' ? 'special' : (pc.unreadable ? 'special' : 'process');
const out = Object.assign({}, pc, { dup_status, version, prev_candidate_id, prev_hr_status, prev_hr_decided_at, prev_hr_note, route });
if (dup_status !== 'new') out.candidate_id = prev_candidate_id;
if (pc.source === 'eval') out.candidate_id = 'E-' + String(pc.file_name || pc.candidate_id).replace(/[^A-Za-z0-9_]/g, '');
return [{ json: out }];

const d = $('Build Prompts').first().json;
const r = $input.first().json;
const R = $('Build Config').first().json;
let is = true, type = '', reason = 'filter failed, passed through';
const u = (d.usage_list || []).slice();
try {
  const t = (Array.isArray(r.content) ? r.content : []).filter(b => b && b.type === 'text').map(b => String(b.text || '')).join('').replace(/```json|```/g, '').trim();
  const j = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  is = j.is_resume !== false; type = j.type || ''; reason = j.reason || '';
  u.push({ step: 'filter', model: R.rules.model_filter, tokens_in: r.usage.input_tokens || 0, tokens_out: r.usage.output_tokens || 0 });
} catch (e) {}
return [{ json: Object.assign({}, d, { is_resume: is, filter_result: is ? 'resume' : 'junk:' + type, filter_reason: reason, usage_list: u }) }];

const ATTEMPT = 1;
const cfg = $('Build Config').first().json;
const R = cfg.rules, N = cfg.num;
const prev = ATTEMPT === 1 ? $('Parse Filter').first().json : $('Parse 1').first().json;
const resp = $input.first().json;
const usageList = (prev.usage_list || []).slice();
const norm = s => String(s == null ? '' : s).normalize('NFC').replace(/\s+/g, ' ').trim();
const hay = norm(prev.resume_text);
const quoteOk = q => { const n = norm(q); return n.length >= 3 && hay.indexOf(n) !== -1; };

let txt = (resp && Array.isArray(resp.content) ? resp.content : []).filter(b => b && b.type === 'text').map(b => String(b.text || '')).join('');
if (resp && resp.usage) usageList.push({ step: ATTEMPT === 1 ? 'scorer' : 'scorer_retry', model: R.model_scorer, tokens_in: resp.usage.input_tokens || 0, tokens_out: resp.usage.output_tokens || 0 });
let J = null, parseError = '';
try {
  txt = txt.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  J = JSON.parse(txt.slice(a, b + 1));
} catch (e) { parseError = 'invalid JSON'; }
if (!J || typeof J !== 'object' || !Array.isArray(J.criteria) || !Array.isArray(J.jobs) || !Array.isArray(J.must_haves)) { J = null; parseError = parseError || 'schema mismatch'; }

const base = Object.assign({}, prev, { usage_list: usageList, attempt: ATTEMPT });
if (!J) {
  const failFlags = (prev.flags || []).concat(ATTEMPT === 2 ? ['scoring_failed'] : []);
  return [{ json: Object.assign(base, { needs_retry: ATTEMPT === 1, parse_error: parseError, flags: failFlags, tier: ATTEMPT === 2 ? 'ATTENTION' : '', scores: [], total_score: null, must_haves: [], summary: ATTEMPT === 2 ? 'Scoring failed after retry: ' + parseError : '' }) }];
}

const flags = (prev.flags || []).slice();
let unverified = 0;
const today = new Date(prev.today + 'T00:00:00Z');
const todayIdx = today.getUTCFullYear() * 12 + today.getUTCMonth() + 1;
const MON = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
function parseDate(s, isEnd) {
  if (s == null) return null;
  const t = String(s).trim().toLowerCase().replace(/\s+/g, ' ');
  if (/^(present|current|now|to date|today|ongoing)$/.test(t)) return { min: todayIdx, max: todayIdx };
  let m = t.match(/^(\d{4})[-\/.](\d{1,2})$/) || t.match(/^(\d{4})-(\d{1,2})-\d{1,2}$/);
  if (m && +m[2] >= 1 && +m[2] <= 12) { const i = +m[1] * 12 + +m[2]; return { min: i, max: i }; }
  m = t.match(/^(\d{1,2})[-\/.](\d{4})$/);
  if (m && +m[1] >= 1 && +m[1] <= 12) { const i = +m[2] * 12 + +m[1]; return { min: i, max: i }; }
  m = t.match(/^([a-z]{3})[a-z]*\.? (\d{4})$/);
  if (m && MON[m[1]]) { const i = +m[2] * 12 + MON[m[1]]; return { min: i, max: i }; }
  m = t.match(/^(\d{4})$/); if (m) { const y = +m[1]; return isEnd ? { min: y * 12 + 1, max: y * 12 + 12 } : { min: y * 12 + 12, max: y * 12 + 1 }; }
  return null;
}
const RL = cfg.relevance;
const S = { counted: { full: new Set(), part: new Set() }, upper: { full: new Set(), part: new Set() }, confirmed: { full: new Set(), part: new Set() } };
let datesMissing = false;
const jobsOut = [], doubtJobs = [];
J.jobs.forEach(j => {
  const cf = String(j.customer_facing || 'unknown').toLowerCase(), te = String(j.technical || 'unknown').toLowerCase(), pt = String(j.product_type || 'unknown').toLowerCase();
  let confirmed = (!RL.require_customer_facing || cf === 'yes') && (!RL.require_technical || te === 'yes') && RL.product_types.indexOf(pt) !== -1;
  let counted = (!RL.require_customer_facing || cf !== 'no') && (!RL.require_technical || te !== 'no') && (RL.product_types.indexOf(pt) !== -1 || pt === 'unknown');
  if (counted && !quoteOk(j.facts_quote)) { confirmed = false; counted = false; unverified++; }
  const s = parseDate(j.start, false), e = parseDate(j.end, true);
  jobsOut.push({ title: j.title, employer: j.employer, start: j.start, end: j.end, employment_type: j.employment_type, customer_facing: cf, technical: te, product_type: pt, counted: counted ? (confirmed ? 'confirmed' : 'unconfirmed') : 'no' });
  if (!counted) return;
  if (!s || !e) { datesMissing = true; return; }
  const part = ['part_time', 'internship', 'freelance'].indexOf(j.employment_type) !== -1 ? 'part' : 'full';
  for (let i = s.min; i <= e.min; i++) { S.counted[part].add(i); if (confirmed) S.confirmed[part].add(i); }
  for (let i = s.max; i <= e.max; i++) S.upper[part].add(i);
  if (!confirmed) {
    const missing = [];
    if (RL.require_customer_facing && cf !== 'yes') missing.push('customer contact');
    if (RL.require_technical && te !== 'yes') missing.push('technical work');
    if (RL.product_types.indexOf(pt) === -1) missing.push('product type');
    doubtJobs.push((j.employer || j.title || 'job') + ': ' + Math.max(0, e.min - s.min + 1) + ' mo, ' + missing.join(' and ') + ' not stated');
  }
});
function months(X) { let n = X.full.size; X.part.forEach(i => { if (!X.full.has(i)) n += N.part_time_factor; }); return Math.round(n * 10) / 10; }
const monthsMin = months(S.counted), monthsMax = months(S.upper), monthsConfirmed = months(S.confirmed);
if (datesMissing) flags.push('dates_missing');
const c1Level = m => m >= N.c1_l3_months ? 3 : m >= N.c1_l2_months ? 2 : m >= N.c1_l1_months ? 1 : 0;
const outcomeChanges = c1Level(monthsConfirmed) !== c1Level(monthsMin) || (monthsMin >= N.m2_min_months && monthsConfirmed < N.m2_min_months);
const confidence = outcomeChanges ? 'doubt' : 'sure';
const confidenceReason = outcomeChanges ? 'Confirmed ' + monthsConfirmed + ' of ' + monthsMin + ' counted months. ' + doubtJobs.join('; ') : '';

const mhOut = [];
const crit = cfg.criteria;
crit.filter(c => c.type === 'must_have').forEach(c => {
  if (c.computed_by === 'code') {
    let st = 'unknown';
    if (monthsMin >= N.m2_min_months) st = 'met';
    else if (monthsMax < N.m2_min_months && !datesMissing) st = 'not_met';
    mhOut.push({ id: c.id, status: st, evidence: null, explanation: 'counted months ' + monthsMin + ' to ' + monthsMax + ', confirmed ' + monthsConfirmed + ' (code)' });
  } else {
    const m = J.must_haves.filter(x => x.id === c.id)[0] || { status: 'unknown' };
    let st = ['met', 'not_met', 'unknown'].indexOf(m.status) !== -1 ? m.status : 'unknown';
    let ev = m.evidence;
    if (st !== 'unknown' && !quoteOk(ev)) { unverified++; st = 'unknown'; ev = null; }
    mhOut.push({ id: c.id, status: st, evidence: ev, explanation: String(m.explanation || '').slice(0, 300) });
  }
});
const scores = [];
let total = 0;
crit.filter(c => c.type === 'scored').forEach(c => {
  let level = 0, evid = [], explanation = '', verified = true;
  if (c.computed_by === 'code') {
    level = c1Level(monthsMin);
    explanation = 'counted months ' + monthsMin + ', confirmed ' + monthsConfirmed + ' (code)';
  } else {
    const m = J.criteria.filter(x => x.id === c.id)[0];
    if (m) {
      level = Math.max(0, Math.min(3, Math.round(Number(m.level) || 0)));
      evid = (Array.isArray(m.evidence) ? m.evidence : []).filter(q => typeof q === 'string');
      explanation = String(m.explanation || '').slice(0, 300);
      if (level > 0) {
        const good = evid.filter(quoteOk);
        if (!good.length) { level = 0; verified = false; unverified++; } else evid = good;
      }
    }
  }
  const points = Math.round((c.weight * level / 3) * 10) / 10;
  total += points;
  scores.push({ criterion_id: c.id, criterion_name: c.name, weight: c.weight, level, points, evidence_quote: evid.join(' | '), evidence_verified: verified, explanation });
});
total = Math.round(total * 10) / 10;

const allowed = ['possible_injection', 'unreadable_text', 'multiple_candidates', 'language_unclear', 'dates_inconsistent', 'protected_info_present'];
(J.flags || []).forEach(f => { if (f && allowed.indexOf(f.flag) !== -1 && flags.indexOf(f.flag) === -1) flags.push(f.flag); });

if (unverified > 0 && ATTEMPT === 1) {
  return [{ json: Object.assign(base, { needs_retry: true, retry_reason: unverified + ' unverified quote(s)', flags: prev.flags || [], tier: '', scores: [], total_score: null, must_haves: [], summary: '' }) }];
}
if (unverified > 0) flags.push('evidence_unverified');

const blocking = String(R.blocking_flags).split(',').map(s => s.trim()).filter(Boolean);
const hasBlock = flags.some(f => blocking.indexOf(f) !== -1) || flags.indexOf('scoring_failed') !== -1;
const anyNot = mhOut.some(m => m.status === 'not_met'), allMet = mhOut.every(m => m.status === 'met');
let tier;
if (hasBlock) tier = 'ATTENTION';
else if (anyNot) tier = 'LOW';
else if (total >= N.top_min && allMet) tier = 'TOP';
else if (total >= N.maybe_min) tier = 'MAYBE';
else tier = 'LOW';
const noBackground = !hasBlock && J.jobs.length === 0 && scores.every(x => x.level === 0) && mhOut.every(x => x.status !== 'met');
if (noBackground) { tier = 'JUNK'; base.filter_result = 'junk:no_background'; }
const nearMiss = tier === 'LOW' && total >= N.near_miss_min;
const mhText = mhOut.map(m => m.id + ' ' + m.status).join(', ');
const summary = noBackground ? 'No work history or evidence found in the text. Treated as junk (no background).' : 'Total ' + total + '/100. ' + mhText + '. Relevant months ' + monthsMin + (monthsMax !== monthsMin ? '-' + monthsMax : '') + '. ' + scores.filter(s => s.criterion_id !== 'C1').map(s => s.criterion_id + ' L' + s.level).join(', ') + (nearMiss ? '. Near miss: failed a must-have.' : '') + (confidence === 'doubt' ? '. DOUBT: ' + confidenceReason : '');
const mhStatus = anyNot ? 'not_met' : (allMet ? 'met' : 'unknown');
return [{ json: Object.assign(base, { needs_retry: false, tier, near_miss: nearMiss, total_score: total, scores, must_haves: mhOut, must_have_status: mhStatus, months_relevant_min: monthsMin, months_relevant_max: monthsMax, months_confirmed: monthsConfirmed, confidence, confidence_reason: confidenceReason, flags, jobs: jobsOut, summary, candidate_model: J.candidate || {}, parse_error: '' }) }];

const ATTEMPT = 2;
const cfg = $('Build Config').first().json;
const R = cfg.rules, N = cfg.num;
const prev = ATTEMPT === 1 ? $('Parse Filter').first().json : $('Parse 1').first().json;
const resp = $input.first().json;
const usageList = (prev.usage_list || []).slice();
const norm = s => String(s == null ? '' : s).normalize('NFC').replace(/\s+/g, ' ').trim();
const hay = norm(prev.resume_text);
const quoteOk = q => { const n = norm(q); return n.length >= 3 && hay.indexOf(n) !== -1; };

let txt = (resp && Array.isArray(resp.content) ? resp.content : []).filter(b => b && b.type === 'text').map(b => String(b.text || '')).join('');
if (resp && resp.usage) usageList.push({ step: ATTEMPT === 1 ? 'scorer' : 'scorer_retry', model: R.model_scorer, tokens_in: resp.usage.input_tokens || 0, tokens_out: resp.usage.output_tokens || 0 });
let J = null, parseError = '';
try {
  txt = txt.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  J = JSON.parse(txt.slice(a, b + 1));
} catch (e) { parseError = 'invalid JSON'; }
if (!J || typeof J !== 'object' || !Array.isArray(J.criteria) || !Array.isArray(J.jobs) || !Array.isArray(J.must_haves)) { J = null; parseError = parseError || 'schema mismatch'; }

const base = Object.assign({}, prev, { usage_list: usageList, attempt: ATTEMPT });
if (!J) {
  const failFlags = (prev.flags || []).concat(ATTEMPT === 2 ? ['scoring_failed'] : []);
  return [{ json: Object.assign(base, { needs_retry: ATTEMPT === 1, parse_error: parseError, flags: failFlags, tier: ATTEMPT === 2 ? 'ATTENTION' : '', scores: [], total_score: null, must_haves: [], summary: ATTEMPT === 2 ? 'Scoring failed after retry: ' + parseError : '' }) }];
}

const flags = (prev.flags || []).slice();
let unverified = 0;
const today = new Date(prev.today + 'T00:00:00Z');
const todayIdx = today.getUTCFullYear() * 12 + today.getUTCMonth() + 1;
const MON = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
function parseDate(s, isEnd) {
  if (s == null) return null;
  const t = String(s).trim().toLowerCase().replace(/\s+/g, ' ');
  if (/^(present|current|now|to date|today|ongoing)$/.test(t)) return { min: todayIdx, max: todayIdx };
  let m = t.match(/^(\d{4})[-\/.](\d{1,2})$/) || t.match(/^(\d{4})-(\d{1,2})-\d{1,2}$/);
